begin;
create extension if not exists pgtap with schema extensions;
select plan(28);
set local role authenticated;
select set_config('request.jwt.claim.sub','20000000-0000-0000-0000-000000000002',true);
select throws_ok($$insert into public.hermes_connections(company_id,owner_id,address,profile,key_encrypted,state) values ('10000000-0000-0000-0000-000000000001',auth.uid(),'http://localhost','writer','ciphertext','connected')$$,'42501',null,'a Manager cannot connect');
select set_config('request.jwt.claim.sub','20000000-0000-0000-0000-000000000001',true);
select lives_ok($$insert into public.hermes_connections(id,company_id,owner_id,address,profile,key_encrypted,state) values ('c0000000-0000-0000-0000-000000000001','10000000-0000-0000-0000-000000000001',auth.uid(),'http://localhost','writer','ciphertext','connected')$$,'the Owner connects without two-step verification');
select is((select count(id)::int from public.hermes_connections),1,'the Owner reads their Company''s Connection');
select throws_ok($$select key_encrypted from public.hermes_connections$$,'42501',null,'even the Owner cannot read ciphertext');
select lives_ok($$update public.hermes_connections set key_encrypted='replacement' where id='c0000000-0000-0000-0000-000000000001'$$,'the Owner replaces the key');
-- The kept key goes only where it was entered: no company agent uses this Connection, and it still cannot be retargeted.
select lives_ok($$update public.hermes_connections set address='http://localhost',profile='writer',key_encrypted='rotated' where id='c0000000-0000-0000-0000-000000000001'$$,'a rotation that repeats the address and profile is kept');
select throws_ok($$update public.hermes_connections set address='https://elsewhere.example' where id='c0000000-0000-0000-0000-000000000001'$$,'42501','hermesDestinationFixed','the Owner cannot point a saved Connection at another address');
select throws_ok($$update public.hermes_connections set profile='other' where id='c0000000-0000-0000-0000-000000000001'$$,'42501','hermesDestinationFixed','the Owner cannot point a saved Connection at another profile');
select throws_ok($$update public.hermes_connections set owner_id='20000000-0000-0000-0000-000000000002'$$,'42501',null,'ownership cannot be reassigned');
select lives_ok($$insert into public.hermes_connections(id,company_id,owner_id,address,profile,key_encrypted,state) values ('c0000000-0000-0000-0000-000000000002','10000000-0000-0000-0000-000000000002',auth.uid(),'http://localhost','writer','ciphertext','connected')$$,'the Owner connects in another Company they own');
reset role;
update public.members set role='owner' where company_id='10000000-0000-0000-0000-000000000001' and person_id='20000000-0000-0000-0000-000000000002';
set local role authenticated;
select set_config('request.jwt.claim.sub','20000000-0000-0000-0000-000000000002',true);
select is((select state from public.hermes_connections),'connected','a second Owner sees only their Company''s Connection state');
select throws_ok($$select key_encrypted from public.hermes_connections$$,'42501',null,'a second Owner cannot read ciphertext');
select throws_ok($$insert into public.hermes_connections(company_id,owner_id,address,profile,key_encrypted,state) values ('10000000-0000-0000-0000-000000000001','20000000-0000-0000-0000-000000000001','http://localhost','writer','ciphertext','connected')$$,'42501',null,'a second Owner cannot connect in another Owner''s name');
with changed as (update public.hermes_connections set key_encrypted='second' returning id) select is((select count(*)::int from changed),1,'a second Owner replaces the key of their Company''s Connection only');
with removed as (delete from public.hermes_connections where company_id='10000000-0000-0000-0000-000000000002' returning id) select is((select count(*)::int from removed),0,'an Owner cannot remove a Connection of a Company they do not own');
reset role;
update public.members set role='manager' where company_id='10000000-0000-0000-0000-000000000001' and person_id='20000000-0000-0000-0000-000000000002';
set local role authenticated;
select is((select count(id)::int from public.hermes_connections),0,'Manager cannot read Connections');
select set_config('request.jwt.claim.sub','30000000-0000-0000-0000-000000000001',true);
select is((select count(id)::int from public.hermes_connections),0,'an agent Contributor cannot read Connections');
select set_config('request.jwt.claim.sub','20000000-0000-0000-0000-000000000003',true);
select is((select count(id)::int from public.hermes_connections),0,'Contributor cannot read Connections');
select set_config('request.jwt.claim.sub','20000000-0000-0000-0000-000000000004',true);
select is((select count(id)::int from public.hermes_connections),0,'Viewer cannot read Connections');
reset role;
-- Aleem's Owner makes the Manager an Owner there (guard_member: only an Owner assigns Owner).
select set_config('request.jwt.claim.sub','20000000-0000-0000-0000-000000000001',true);
insert into public.members(company_id,person_id,role) values ('10000000-0000-0000-0000-000000000003','20000000-0000-0000-0000-000000000002','owner');
set local role authenticated;
select set_config('request.jwt.claim.sub','20000000-0000-0000-0000-000000000002',true);
select is((select count(id)::int from public.hermes_connections),0,'an Owner of another Company sees no Connection here');
with changed as (update public.hermes_connections set key_encrypted='forbidden' returning id) select is((select count(*)::int from changed),0,'an Owner of another Company cannot replace');
with removed as (delete from public.hermes_connections returning id) select is((select count(*)::int from removed),0,'an Owner of another Company cannot remove');
select throws_ok($$insert into public.hermes_connections(company_id,owner_id,address,profile,key_encrypted,state) values ('10000000-0000-0000-0000-000000000001','20000000-0000-0000-0000-000000000001','http://localhost','writer','ciphertext','connected')$$,'42501',null,'an Owner of another Company cannot create as this Owner');
select set_config('request.jwt.claim.sub','20000000-0000-0000-0000-000000000001',true);
with removed as (delete from public.hermes_connections where id='c0000000-0000-0000-0000-000000000001' returning id) select is((select count(*)::int from removed),1,'the Owner removes the Connection');
set local role anon;
select throws_ok($$select id from public.hermes_connections$$,'42501',null,'anonymous callers cannot read');
reset role;
select ok(not has_column_privilege('authenticated','public.hermes_connections','company_id','update'),'company cannot be changed');
select throws_ok($$update public.hermes_connections set address='https://elsewhere.example' where id='c0000000-0000-0000-0000-000000000002'$$,'42501','hermesDestinationFixed','direct database access cannot retarget a Connection either');
select ok((select relrowsecurity from pg_class where oid='public.hermes_connections'::regclass),'RLS protects Connections');
select * from finish();
rollback;
